import{_ as t,o as a,c as r,ai as o}from"./chunks/framework.DQi1ytmF.js";const f=JSON.parse('{"title":"Adopting CraftTS progressively","description":"","frontmatter":{},"headers":[],"relativePath":"resources/effect-adoption.md","filePath":"resources/effect-adoption.md"}'),i={name:"resources/effect-adoption.md"};function n(s,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/resources/effect-adoption.md for this page in Markdown format</div><h1 id="adopting-craftts-progressively" tabindex="-1">Adopting CraftTS progressively <a class="header-anchor" href="#adopting-craftts-progressively" aria-label="Permalink to &quot;Adopting CraftTS progressively&quot;">​</a></h1><p>You do not need to rewrite an Effect application before evaluating CraftTS. Keep the domain programs and Layers intact, then introduce Craft at the browser boundary one feature at a time.</p><h2 id="recommended-path" tabindex="-1">Recommended path <a class="header-anchor" href="#recommended-path" aria-label="Permalink to &quot;Recommended path&quot;">​</a></h2><h3 id="_0-establish-the-constraints" tabindex="-1">0. Establish the constraints <a class="header-anchor" href="#_0-establish-the-constraints" aria-label="Permalink to &quot;0. Establish the constraints&quot;">​</a></h3><p>Before changing application code, confirm the <a href="/craft/resources/effect-compatibility.html">compatibility matrix</a>. In particular, check the Effect 4 release-candidate requirement, the Node version and whether SSR is a hard requirement.</p><h3 id="_1-keep-the-domain-in-effect" tabindex="-1">1. Keep the domain in Effect <a class="header-anchor" href="#_1-keep-the-domain-in-effect" aria-label="Permalink to &quot;1. Keep the domain in Effect&quot;">​</a></h3><p>Select one existing operation with a clear type:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Effect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Output, BusinessError, RequiredServices</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Keep its <code>Context.Service</code>, <code>Layer</code>, tagged errors and tests. The first Craft change should be an adapter, not a rewrite of the business logic.</p><h3 id="_2-add-the-craft-boundary" tabindex="-1">2. Add the Craft boundary <a class="header-anchor" href="#_2-add-the-craft-boundary" aria-label="Permalink to &quot;2. Add the Craft boundary&quot;">​</a></h3><p>Install <code>@craft-ts/effect</code>, install the bridge once at bootstrap, and expose the operation through <code>queryEffect</code>, <code>mutationEffect</code> or <code>asyncProcessEffect</code>.</p><p>The component should call the domain operation. It should not resolve the repository, call <code>Effect.runPromise</code>, start a fiber from a click handler or duplicate the domain state in a Craft <code>state</code>.</p><h3 id="_3-pilot-one-read-only-feature" tabindex="-1">3. Pilot one read-only feature <a class="header-anchor" href="#_3-pilot-one-read-only-feature" aria-label="Permalink to &quot;3. Pilot one read-only feature&quot;">​</a></h3><p>Start with a page that has:</p><ul><li>one query;</li><li>one application or route Layer;</li><li>one loading state;</li><li>one typed business error;</li><li>one technical error path;</li><li>one executable test.</li></ul><p>This exposes the real cost of the Craft UI model without mixing in forms, optimistic updates or server-function transport.</p><h3 id="_4-add-writes-and-forms" tabindex="-1">4. Add writes and forms <a class="header-anchor" href="#_4-add-writes-and-forms" aria-label="Permalink to &quot;4. Add writes and forms&quot;">​</a></h3><p>Once the read path is stable, add <code>mutationEffect</code>, then connect it to Craft forms and <code>insertReactOnMutation</code>. Keep validation responsibilities explicit:</p><ul><li>Effect Schema or <code>methodSchema</code> validates a boundary payload;</li><li>Craft owns field state, validity and interaction;</li><li>Effect typed errors represent business rejection;</li><li>defects remain technical failures.</li></ul><h3 id="_5-introduce-route-and-feature-scopes" tabindex="-1">5. Introduce route and feature scopes <a class="header-anchor" href="#_5-introduce-route-and-feature-scopes" aria-label="Permalink to &quot;5. Introduce route and feature scopes&quot;">​</a></h3><p>Move a Layer to the narrowest scope that owns it. Add the compile-time Effect requirements proof for the route, and keep route providers in a named tuple so the type checker can inspect them.</p><p>Do this after the first feature works. The proof is valuable, but introducing it before the boundary is understood makes the first experiment look more complex than it is.</p><h3 id="_6-evaluate-server-functions-separately" tabindex="-1">6. Evaluate server functions separately <a class="header-anchor" href="#_6-evaluate-server-functions-separately" aria-label="Permalink to &quot;6. Evaluate server functions separately&quot;">​</a></h3><p>Treat the current server-function integration as a separate experiment. Its transport, file conventions, middleware API and deployment integration are not final. Never treat a client Layer as an authentication or authorization boundary; the server must verify claims again.</p><h2 id="what-can-stay-and-what-changes" tabindex="-1">What can stay and what changes? <a class="header-anchor" href="#what-can-stay-and-what-changes" aria-label="Permalink to &quot;What can stay and what changes?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Existing Effect application asset</th><th>During a Craft pilot</th></tr></thead><tbody><tr><td>Domain types and business operations</td><td>Keep</td></tr><tr><td>Tagged errors and error unions</td><td>Keep; map at the Craft boundary</td></tr><tr><td><code>Context.Service</code> contracts</td><td>Keep</td></tr><tr><td>Live and test <code>Layer</code>s</td><td>Keep; expose through <code>provideLayer</code></td></tr><tr><td>Effect unit tests</td><td>Keep</td></tr><tr><td>Existing UI components and templates</td><td>Keep outside the pilot; replace only the selected Craft feature</td></tr><tr><td>UI loading, cancellation and rendering state</td><td>Move to Craft resources</td></tr><tr><td>URL state and form interaction</td><td>Model with Craft primitives and forms</td></tr></tbody></table><h2 id="go-no-go-signals" tabindex="-1">Go / no-go signals <a class="header-anchor" href="#go-no-go-signals" aria-label="Permalink to &quot;Go / no-go signals&quot;">​</a></h2><p>Proceed when the pilot has a clear resource boundary, an executable Layer setup and tests that distinguish business errors from defects.</p><p>Pause and resolve the issue before expanding when:</p><ul><li>the project is still on Effect 3 without an isolation plan;</li><li>SSR is mandatory but no SSR host has been selected;</li><li>the team cannot explain which side owns a piece of state;</li><li>every feature requires a custom bridge or manual subscription;</li><li>typecheck time or type errors make the feedback loop unacceptable.</li></ul>',31)])])}const u=t(i,[["render",n]]);export{f as __pageData,u as default};
